function demoMain(idx,label){
  var branches=[["main","feature/login","hotfix/crash"],["main","feature/api","release/2.0"],["main","feature/ui"]];
  var b=branches[idx%branches.length];
  return "["+label+"] branches: "+b.join(", ")+" | merged: "+(b.length-1)+" into main, 0 conflicts";
}

